import java.util.*;
import java.io.*;

public class GG {
    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();
        PrintWriter out = new PrintWriter(System.out);
        int N = scanner.nextInt();
        int M = scanner.nextInt();
        int K = scanner.nextInt();
        int C = scanner.nextInt();
        int D = scanner.nextInt();
        ArrayMinCostFlow solver = new ArrayMinCostFlow();
        int[] people = new int[K];
        for(int i = 0; i < K; i++) people[i] = scanner.nextInt()-1;
        int src = solver.addNode();
        int snk = solver.addNode();
        int amt = 150;
        int[][] timeNodes = new int[N][amt];
        for(int i = 0; i < N; i++) {
            for(int j = 1; j < amt; j++) {
                timeNodes[i][j] = solver.addNode();
                if (j > 1) solver.link(timeNodes[i][j-1], timeNodes[i][j], Integer.MAX_VALUE, 0);
            }
        }
        for(int i = 0; i < K; i++) {
            solver.link(src, timeNodes[people[i]][1], 1, 0);
        }
        for(int i = 1; i < amt; i++) {
            for(int j = 0; j < K; j++) {
                solver.link(timeNodes[0][i], snk, 1, C*i-C);
            }
        }
        for(int i =0; i < M; i++) {
            int a = scanner.nextInt()-1;
            int b = scanner.nextInt()-1;
            for(int j = 1; j < amt-1; j++) {
                int prev = 0;
                for(int k = 1; k <= K; k++) {
                    solver.link(timeNodes[a][j], timeNodes[b][j + 1], 1, D*k*k- prev);
                    solver.link(timeNodes[b][j], timeNodes[a][j + 1], 1, D*k*k - prev);
                    prev = D * k * k;
                }
            }
        }
        long[] ret = solver.getMinCostMaxFlow(src, snk);
        out.println(ret[1]);
        out.flush();
    }

    // Array-based graph representation
    static class ArrayMinCostFlow {
        int nodeCount;
        int[] head;
        int[] to;
        int[] next;
        long[] cap;
        long[] cost;
        int edgeCount;
        long minCost;
        static final long INF = Long.MAX_VALUE/4;

        ArrayMinCostFlow() {
            nodeCount = 0;
            head = new int[1];
            to = new int[1];
            next = new int[1];
            cap = new long[1];
            cost = new long[1];
            edgeCount = 0;
        }

        int addNode() {
            if (nodeCount >= head.length) {
                head = Arrays.copyOf(head, head.length*2);
            }
            head[nodeCount] = -1;
            return nodeCount++;
        }

        void link(int u, int v, long capacity) {
            link(u, v, capacity, 1);
        }

        void link(int u, int v, long capacity, long c) {
            // add forward edge
            if (edgeCount >= to.length) {
                int newSize = to.length*2;
                to = Arrays.copyOf(to, newSize);
                next = Arrays.copyOf(next, newSize);
                cap = Arrays.copyOf(cap, newSize);
                cost = Arrays.copyOf(cost, newSize);
            }
            to[edgeCount] = v;
            next[edgeCount] = head[u];
            head[u] = edgeCount;
            cap[edgeCount] = capacity;
            cost[edgeCount] = c;
            edgeCount++;
            // add backward edge
            if (edgeCount >= to.length) {
                int newSize = to.length*2;
                to = Arrays.copyOf(to, newSize);
                next = Arrays.copyOf(next, newSize);
                cap = Arrays.copyOf(cap, newSize);
                cost = Arrays.copyOf(cost, newSize);
            }
            to[edgeCount] = u;
            next[edgeCount] = head[v];
            head[v] = edgeCount;
            cap[edgeCount] = 0;
            cost[edgeCount] = -c;
            edgeCount++;
        }

        long[] getMinCostMaxFlow(int src, int snk) {
            long flow = 0;
            long cost = 0;
            int n = nodeCount;
            long[] potential = new long[n];
            while (true) {
                int[] parent = new int[n];
                long[] dist = new long[n];
                Arrays.fill(dist, INF);
                dist[src] = 0;
                PriorityQueue<Item> que = new PriorityQueue<Item>();
                que.add(new Item(0, src));
                while (!que.isEmpty()) {
                    Item item = que.poll();
                    if (item.dist != dist[item.v]) continue;
                    for (int e = head[item.v]; e != -1; e = next[e]) {
                        if (cap[e] > 0) {
                            long temp = dist[item.v] + cost[e] + potential[item.v] - potential[to[e]];
                            if (dist[to[e]] > temp) {
                                dist[to[e]] = temp;
                                parent[to[e]] = e;
                                que.add(new Item(temp, to[e]));
                            }
                        }
                    }
                }
                if (parent[snk] == -1) break;
                for (int i = 0; i < n; i++)
                    if (parent[i] != -1) potential[i] += dist[i];
                long augFlow = Long.MAX_VALUE;
                for (int i = snk; i != src; i = to[parent[i]^1]) {
                    augFlow = Math.min(augFlow, cap[parent[i]]);
                }
                for (int i = snk; i != src; i = to[parent[i]^1]) {
                    cap[parent[i]] -= augFlow;
                    cap[parent[i]^1] += augFlow;
                    cost += augFlow * cost[parent[i]];
                }
                flow += augFlow;
            }
            minCost = cost;
            return new long[]{flow, cost};
        }

        static class Item implements Comparable<Item> {
            long dist;
            int v;
            Item(long d, int v) { this.dist = d; this.v = v; }
            public int compareTo(Item o) { return Long.compare(this.dist, o.dist); }
        }
    }

    public static class FastScanner {
        BufferedReader br;
        StringTokenizer st;
        public FastScanner(Reader in) { br = new BufferedReader(in); }
        public FastScanner() { this(new InputStreamReader(System.in)); }
        String next() {
            while (st == null || !st.hasMoreElements()) {
                try { st = new StringTokenizer(br.readLine()); } catch (IOException e) { e.printStackTrace(); }
            }
            return st.nextToken();
        }
        int nextInt() { return Integer.parseInt(next()); }
        long nextLong() { return Long.parseLong(next()); }
        double nextDouble() { return Double.parseDouble(next()); }
        String readNextLine() {
            String str = "";
            try { str = br.readLine(); } catch (IOException e) { e.printStackTrace(); }
            return str;
        }
        int[] readIntArray(int n) {
            int[] a = new int[n];
            for (int idx = 0; idx < n; idx++) a[idx] = nextInt();
            return a;
        }
    }
}
